package com.bank.sec;

import java.util.*;

// The least-privilege knobs. Defaults here are the INSECURE defaults.
public class PodSecurityContext {
    boolean runAsNonRoot = false;      // secure: true
    int runAsUser = 0;                 // secure: non-zero, e.g. 10001
    boolean readOnlyRootFilesystem = false; // secure: true
    boolean allowPrivilegeEscalation = true; // secure: false
    List<String> capabilitiesAdded = new ArrayList<>(List.of("ALL")); // secure: drop ALL
    String seccompProfile = "Unconfined"; // secure: RuntimeDefault

    public static PodSecurityContext hardened() {
        PodSecurityContext c = new PodSecurityContext();
        c.runAsNonRoot = true; c.runAsUser = 10001; c.readOnlyRootFilesystem = true;
        c.allowPrivilegeEscalation = false; c.capabilitiesAdded = new ArrayList<>();
        c.seccompProfile = "RuntimeDefault";
        return c;
    }
}
