package com.bank.sec;

import java.util.*;
import java.util.logging.Logger;

// Enforces the restricted profile at admission: reject root / escalation / extra caps.
public class PodSecurityAdmission {
    private static final Logger log = Logger.getLogger(PodSecurityAdmission.class.getName());

    public boolean admit(String podName, PodSecurityContext ctx) {
        List<String> violations = new ArrayList<>();
        if (!ctx.runAsNonRoot || ctx.runAsUser == 0) violations.add("must runAsNonRoot (non-zero UID)");
        if (!ctx.readOnlyRootFilesystem) violations.add("root filesystem must be read-only");
        if (ctx.allowPrivilegeEscalation) violations.add("allowPrivilegeEscalation must be false");
        if (!ctx.capabilitiesAdded.isEmpty()) violations.add("must drop ALL capabilities (added=" + ctx.capabilitiesAdded + ")");
        if (!"RuntimeDefault".equals(ctx.seccompProfile)) violations.add("seccomp must be RuntimeDefault");

        if (violations.isEmpty()) { log.info(() -> "ADMIT " + podName + " (restricted profile satisfied)"); return true; }
        log.severe(() -> "REJECT " + podName + " — restricted profile violations: " + violations);
        return false;
    }
}
