package com.bank.sec;

import java.util.logging.Logger;

// Estimates attacker reach if the app is compromised.
public class BlastRadius {
    private static final Logger log = Logger.getLogger(BlastRadius.class.getName());

    public void estimate(PodSecurityContext ctx) {
        if (ctx.runAsUser == 0 || ctx.allowPrivilegeEscalation || !ctx.capabilitiesAdded.isEmpty()) {
            log.severe("blast radius: HIGH — root + caps + escalation -> container escape -> NODE takeover -> all Pods' secrets");
        } else {
            log.info("blast radius: LOW — unprivileged UID, read-only FS, no caps, no escalation -> contained to this app");
        }
    }
}
