package com.bank.sec;

import java.math.BigDecimal;
import java.util.logging.*;

public class PodSecurityDemo {
    private static final Logger log = Logger.getLogger(PodSecurityDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        PodSecurityAdmission admission = new PodSecurityAdmission();
        BlastRadius blast = new BlastRadius();

        // Insecure Pod: runs as root -> rejected
        PodSecurityContext rootCtx = new PodSecurityContext();
        blast.estimate(rootCtx);
        admission.admit("transfer-root", rootCtx);

        // Hardened Pod: least privilege -> admitted, then serves traffic
        PodSecurityContext hard = PodSecurityContext.hardened();
        blast.estimate(hard);
        if (admission.admit("transfer-hardened", hard)) {
            rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
            log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on hardened pod (UID 10001, RO FS, no caps)");
        }
    }
}
