# k8s/deployment.yaml — hardened securityContext
spec:
  template:
    spec:
      securityContext:
        runAsNonRoot: true
        runAsUser: 10001
        seccompProfile: { type: RuntimeDefault }
      containers:
        - name: transfer
          image: nbi/transfer-service:v7
          securityContext:
            readOnlyRootFilesystem: true
            allowPrivilegeEscalation: false
            capabilities: { drop: ["ALL"] }
          volumeMounts:
            - { name: tmp, mountPath: /tmp }   # writable scratch since root FS is read-only
      volumes:
        - name: tmp
          emptyDir: {}
---
# k8s/namespace-pss.yaml — enforce the restricted profile cluster-side
apiVersion: v1
kind: Namespace
metadata:
  name: banking-prod
  labels:
    pod-security.kubernetes.io/enforce: restricted
    pod-security.kubernetes.io/warn: restricted
    pod-security.kubernetes.io/audit: restricted
